messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>3D Humanoid Treadmill Animation</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #1a1a1a; }
        canvas { display: block; }
    </style>
</head>
<body>
    <script type="importmap">
        {
            "imports": {
                "three": "./three.module.js"
            }
        }
    </script>
    <script type="module">
        import * as THREE from './three.module.js';

        // --- SCENE SETUP ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x202025);
        scene.fog = new THREE.Fog(0x202025, 10, 50);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 2, 12); // Side-on camera
        camera.lookAt(0, 1, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        // --- LIGHTING ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.4);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1);
        dirLight.position.set(5, 10, 5);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 1024;
        dirLight.shadow.mapSize.height = 1024;
        scene.add(dirLight);

        const rimLight = new THREE.DirectionalLight(0x4444ff, 0.5);
        rimLight.position.set(-5, 5, -5);
        scene.add(rimLight);

        // --- MATERIALS ---
        const skinMat = new THREE.MeshStandardMaterial({ color: 0xffccaa, roughness: 0.5 });
        const shirtMat = new THREE.MeshStandardMaterial({ color: 0x3366cc, roughness: 0.7 });
        const pantsMat = new THREE.MeshStandardMaterial({ color: 0x222222, roughness: 0.8 });
        const shoeMat = new THREE.MeshStandardMaterial({ color: 0x888888, roughness: 0.4 });
        const treadmillMat = new THREE.MeshStandardMaterial({ color: 0x333333, roughness: 0.2 });
        const beltMat = new THREE.MeshStandardMaterial({ color: 0x111111 });

        // --- TREADMILL ---
        const treadmillGroup = new THREE.Group();

        // Belt
        const beltGeo = new THREE.BoxGeometry(4, 0.2, 6);
        const belt = new THREE.Mesh(beltGeo, treadmillMat);
        belt.position.y = -0.1;
        belt.receiveShadow = true;
        treadmillGroup.add(belt);

        // Side rails
        const railGeo = new THREE.BoxGeometry(0.2, 0.8, 6);
        const leftRail = new THREE.Mesh(railGeo, treadmillMat);
        leftRail.position.set(-2.1, 0.3, 0);
        leftRail.castShadow = true;
        treadmillGroup.add(leftRail);

        const rightRail = new THREE.Mesh(railGeo, treadmillMat);
        rightRail.position.set(2.1, 0.3, 0);
        rightRail.castShadow = true;
        treadmillGroup.add(rightRail);

        // Console/Screen
        const consoleGeo = new THREE.BoxGeometry(0.5, 2, 0.5);
        const console = new THREE.Mesh(consoleGeo, treadmillMat);
        console.position.set(0, 1.5, -2.8);
        console.castShadow = true;
        treadmillGroup.add(console);

        scene.add(treadmillGroup);

        // --- HUMANOID FIGURE ---
        const humanoid = new THREE.Group();
        humanoid.position.set(0, 0, 0);
        scene.add(humanoid);

        // Helper to create limb with pivot
        function createLimb(width, height, depth, material) {
            const geo = new THREE.BoxGeometry(width, height, depth);
            const mesh = new THREE.Mesh(geo, material);
            mesh.castShadow = true;
            mesh.receiveShadow = true;
            // Pivot at top
            mesh.geometry.translate(0, -height / 2, 0);
            return mesh;
        }

        // 1. TORSO (Upper Body)
        const torso = new THREE.Group();
        torso.position.y = 1.4; // Hip height
        humanoid.add(torso);

        // Torso Mesh
        const torsoMesh = new THREE.Mesh(new THREE.BoxGeometry(0.6, 0.7, 0.3), shirtMat);
        torsoMesh.position.y = 0.35; // Center relative to group
        torso.add(torsoMesh);

        // Neck
        const neck = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.1, 0.15), skinMat);
        neck.position.y = 0.75;
        torso.add(neck);

        // 2. HEAD
        const head = new THREE.Group();
        head.position.y = 0.85;
        torso.add(head);

        const headMesh = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.35, 0.3), skinMat);
        headMesh.position.y = 0.175;
        head.add(headMesh);

        // Eyes (to see face direction)
        const eyeGeo = new THREE.BoxGeometry(0.05, 0.05, 0.05);
        const eyeMat = new THREE.MeshBasicMaterial({ color: 0x000000 });
        const leftEye = new THREE.Mesh(eyeGeo, eyeMat);
        leftEye.position.set(-0.08, 0.2, 0.15);
        head.add(leftEye);
        const rightEye = new THREE.Mesh(eyeGeo, eyeMat);
        rightEye.position.set(0.08, 0.2, 0.15);
        head.add(rightEye);

        // 3. ARMS
        // Left Arm
        const leftShoulder = new THREE.Group();
        leftShoulder.position.set(-0.35, 0.6, 0);
        torso.add(leftShoulder);

        const leftUpperArm = createLimb(0.15, 0.35, 0.15, shirtMat);
        leftShoulder.add(leftUpperArm);

        const leftElbow = new THREE.Group();
        leftElbow.position.set(0, -0.35, 0);
        leftUpperArm.add(leftElbow);

        const leftForearm = createLimb(0.12, 0.35, 0.12, skinMat);
        leftElbow.add(leftForearm);

        // Right Arm
        const rightShoulder = new THREE.Group();
        rightShoulder.position.set(0.35, 0.6, 0);
        torso.add(rightShoulder);

        const rightUpperArm = createLimb(0.15, 0.35, 0.15, shirtMat);
        rightShoulder.add(rightUpperArm);

        const rightElbow = new THREE.Group();
        rightElbow.position.set(0, -0.35, 0);
        rightUpperArm.add(rightElbow);

        const rightForearm = createLimb(0.12, 0.35, 0.12, skinMat);
        rightElbow.add(rightForearm);

        // 4. LEGS
        // Left Leg
        const leftHip = new THREE.Group();
        leftHip.position.set(-0.2, 0, 0);
        torso.add(leftHip);

        const leftThigh = createLimb(0.2, 0.45, 0.2, pantsMat);
        leftHip.add(leftThigh);

        const leftKnee = new THREE.Group();
        leftKnee.position.set(0, -0.45, 0);
        leftThigh.add(leftKnee);

        const leftShin = createLimb(0.18, 0.45, 0.18, pantsMat);
        leftKnee.add(leftShin);

        // Left Foot
        const leftFoot = new THREE.Mesh(new THREE.BoxGeometry(0.15, 0.1, 0.35), shoeMat);
        leftFoot.position.set(0, -0.45, 0.1); // Slightly forward at end of shin
        leftShin.add(leftFoot);

        // Right Leg
        const rightHip = new THREE.Group();
        rightHip.position.set(0.2, 0, 0);
        torso.add(rightHip);

        const rightThigh = createLimb(0.2, 0.45, 0.2, pantsMat);
        rightHip.add(rightThigh);

        const rightKnee = new THREE.Group();
        rightKnee.position.set(0, -0.45, 0);
        rightThigh.add(rightKnee);

        const rightShin = createLimb(0.18, 0.45, 0.18, pantsMat);
        rightKnee.add(rightShin);

        // Right Foot
        const rightFoot = new THREE.Mesh(new THREE.BoxGeometry(0.15, 0.1, 0.35), shoeMat);
        rightFoot.position.set(0, -0.45, 0.1);
        rightShin.add(rightFoot);

        // --- ANIMATION STATE ---
        const CYCLE_DURATION = 10.0;
        const STAND_STILL_DUR = 2.0;
        const WALK_DUR = 3.0;
        const RUN_DUR = 3.0;

        // Animation parameters
        const WALK_SPEED = 6.0; // Radians per second
        const RUN_SPEED = 12.0;

        // Amplitudes (Max angles in radians)
        const WALK_LIMB_SWING = 0.8;
        const RUN_LIMB_SWING = 1.2;

        // Elbow/Front lean offsets
        const WALK_ARM_SWING = 0.6;
        const RUN_ARM_SWING = 1.0;

        // Torso Lean (Forward rotation X)
        const WALK_LEAN = 0.05;
        const RUN_LEAN = 0.25;

        // Helper: Smoothstep
        function smoothstep(edge0, edge1, x) {
            const t = Math.max(0, Math.min(1, (x - edge0) / (edge1 - edge0)));
            return t * t * (3 - 2 * t);
        }

        // State variables
        let cycleTime = 0;
        let currentPhase = 'stand'; // stand, walk, run, stand
        let phaseTime = 0;

        // Interpolation variables
        let targetLean = 0;
        let currentLean = 0;
        let targetSpeed = 0;
        let currentSpeed = 0;
        let targetSwing = 0;
        let currentSwing = 0;

        function updateHumanoid(dt) {
            cycleTime += dt;
            if (cycleTime > CYCLE_DURATION) cycleTime -= CYCLE_DURATION;

            // Determine Phase
            if (cycleTime < STAND_STILL_DUR) {
                currentPhase = 'stand';
            } else if (cycleTime < STAND_STILL_DUR + WALK_DUR) {
                currentPhase = 'walk';
            } else if (cycleTime < STAND_STILL_DUR + WALK_DUR + RUN_DUR) {
                currentPhase = 'run';
            } else {
                currentPhase = 'stand';
            }

            // Calculate Phase Progress (0 to 1)
            let phaseProgress = 0;
            if (currentPhase === 'stand') {
                phaseProgress = cycleTime / STAND_STILL_DUR;
            } else if (currentPhase === 'walk') {
                phaseProgress = (cycleTime - STAND_STILL_DUR) / WALK_DUR;
            } else if (currentPhase === 'run') {
                phaseProgress = (cycleTime - STAND_STILL_DUR - WALK_DUR) / RUN_DUR;
            } else {
                phaseProgress = (cycleTime - STAND_STILL_DUR - WALK_DUR - RUN_DUR) / STAND_STILL_DUR;
            }

            // Smooth transitions between phases (0.2s transition window)
            const transDur = 0.2;

            // Determine target values based on phase
            let tLean = 0, tSpeed = 0, tSwing = 0;

            if (currentPhase === 'stand') {
                tLean = 0; tSpeed = 0; tSwing = 0;
            } else if (currentPhase === 'walk') {
                tLean = WALK_LEAN; tSpeed = WALK_SPEED; tSwing = WALK_LIMB_SWING;
            } else if (currentPhase === 'run') {
                tLean = RUN_LEAN; tSpeed = RUN_SPEED; tSwing = RUN_LIMB_SWING;
            }

            // Smooth interpolation towards targets
            // If we are just entering a phase, we need to ramp up.
            // If we are leaving a phase, we ramp down.

            // Simple approach: Lerp towards target with speed dependent on phase change
            const lerpFactor = dt * 10; // Speed of adjustment

            // If transitioning from Stand to Walk/Run, or Walk to Run
            // We can use phaseProgress to blend if we were at the boundary, 
            // but simpler is to just lerp towards the target value defined by current phase.
            // However, to make it look like "walking in place" vs "running", 
            // we need to reset the sine wave phase if we change speed abruptly? 
            // Actually, keeping the phase continuous is better for smoothness.

            // Let's just lerp the parameters
            currentLean += (tLean - currentLean) * lerpFactor;
            currentSpeed += (tSpeed - currentSpeed) * lerpFactor;
            currentSwing += (tSwing - currentSwing) * lerpFactor;

            // Apply Lean to Torso
            torso.rotation.x = -currentLean; // Negative for forward lean

            // Calculate Limb Angles
            // We need to handle the "Start/Stop" of the cycle.
            // If speed is 0, angles should be 0.

            if (currentSpeed > 0.1) {
                // Calculate angle based on accumulated time
                const angle = cycleTime * currentSpeed;

                // --- LEGS ---
                // Walking/Running: Left Leg Forward, Right Leg Back (and vice versa)
                // Sine wave: sin(angle)

                // Left Leg
                leftHip.rotation.x = Math.sin(angle) * currentSwing;
                // Knee bend: bends when leg swings back (positive rotation) or forward?
                // Standard walk: When leg swings forward (negative hip angle), knee bends.
                // When leg swings back (positive hip angle), leg is straight.
                // Let's approximate: Knee bend proportional to -sin(angle) but clamped
                const kneeBendLeft = Math.max(0, -Math.sin(angle)) * 0.8;
                leftKnee.rotation.x = -kneeBendLeft; // Bend backwards relative to thigh

                // Right Leg (Opposite phase)
                rightHip.rotation.x = Math.sin(angle + Math.PI) * currentSwing;
                const kneeBendRight = Math.max(0, -Math.sin(angle + Math.PI)) * 0.8;
                rightKnee.rotation.x = -kneeBendRight;

                // --- ARMS ---
                // Arms swing opposite to legs (Left Arm swings with Right Leg)
                // Left Arm
                leftShoulder.rotation.x = Math.sin(angle + Math.PI) * (currentSwing * 0.8); // Slightly less range for arms usually, but let's match
                // Elbow bends when arm swings back
                const armBendLeft = Math.max(0, Math.sin(angle + Math.PI)) * 0.5;
                leftElbow.rotation.x = -armBendLeft;

                // Right Arm
                rightShoulder.rotation.x = Math.sin(angle) * (currentSwing * 0.8);
                const armBendRight = Math.max(0, Math.sin(angle)) * 0.5;
                rightElbow.rotation.x = -armBendRight;

            } else {
                // Stand Still: Reset to 0
                leftHip.rotation.x = 0;
                leftKnee.rotation.x = 0;
                leftShoulder.rotation.x = 0;
                leftElbow.rotation.x = 0;

                rightHip.rotation.x = 0;
                rightKnee.rotation.x = 0;
                rightShoulder.rotation.x = 0;
                rightElbow.rotation.x = 0;
            }

            // Subtle Head Bob
            if (currentSpeed > 0.1) {
                const bob = Math.abs(Math.sin(cycleTime * currentSpeed)) * 0.05;
                head.position.y = 0.85 - bob;
            } else {
                head.position.y = 0.85;
            }
        }

        // --- RENDER LOOP ---
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const dt = clock.getDelta();

            updateHumanoid(dt);

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
```
